}

/**
 * อ leads in exactly four words. There is no fifth; the branch is closed and
 * the lesson says so.
 */
export const O_LEADING_WORDS: readonly string[] = Object.freeze([
	"อย่า",
	"อยู่",
	"อย่าง",
	"อยาก",
]);

