	{ id: "lesson-03", legacyNumber: 3 },
	{ id: "lesson-04", legacyNumber: 4 },
	{ id: "lesson-05", legacyNumber: 5 },
	{ id: BUCKETS_LESSON_ID },
];

type RawSlide = {
	kind: string;
	id: string;
