/** Sentences, split only on terminal punctuation so a clause keeps its glyphs. */
function sentencesOf(text: string): string[] {
	return text
		.split(/(?<=[.?!])\s+/)
		.map((s) => s.trim())
		.filter((s) => s.length > 0);
}

